mars = subject_image('surface of planet Mars')
orb = subject_image('Mars Climate Orbiter spacecraft')
cx = (RX0 + RX1) // 2
gy = RBOT - 60
top = RTOP + 120
plan, act = values[0], values[1]
def ypos(v):
    return gy - (v / plan) * (gy - top)
if mars is not None:
    paste(mars, RX0, gy - 40, RX1 - RX0, 140)
else:
    d.rectangle([RX0, gy, RX1, gy + 100], fill=rgba(WARN, 200))
yp = ypos(plan)
for xx in range(RX0, RX1, 40):
    d.line([xx, yp, xx + 22, yp], fill=rgba(TEXT, 200), width=4)
text('SAFE ' + fmt(plan), cx, yp - 44, size=40, color=TEXT, center=True)
ya = ypos(act)
t = clamp(reveal * 1.15)
oy = lerp(top - 20, ya, t)
if t > 0.55 and t < 1.0:
    oy = lerp(yp, ya, (t - 0.55) / 0.45)
sway = int(30 * math.sin(reveal * 18))
if orb is not None:
    paste(orb, cx - 90 + sway, int(oy) - 80, 180, 160)
else:
    d.rectangle([cx - 60, int(oy) - 30, cx + 60, int(oy) + 30], fill=rgba(HIGHLIGHT, 230))
for k in range(7):
    ph = (reveal * 3 + k / 7.0) % 1.0
    d.ellipse([cx - 30 + (k * 23) % 60, int(oy) + 70 + int(ph * 90), cx - 10 + (k * 23) % 60, int(oy) + 90 + int(ph * 90)], fill=rgba(HIGHLIGHT, 160))
if t >= 1.0 or reveal > 0.8:
    d.line([RX0, ya, RX1, ya], fill=rgba(WARN, 230), width=6)
    text('ACTUAL ' + fmt(act), cx, ya + 20, size=52, color=WARN, center=True)

person = subject_image('person torso silhouette')
colw = (RX1 - RX0) // 2
for i, (lab, v) in enumerate(zip(labels, values)):
    cx = RX0 + colw * i + colw // 2
    top, h, w = RTOP + 120, 900, 400
    if person is not None:
        paste(person, cx - w // 2, top, w, h)
    else:
        d.rounded_rectangle([cx - w // 2, top, cx + w // 2, top + h], radius=60, outline=rgba(TEXT, 120), width=5)
    frac = clamp(v / 100.0) * clamp(reveal * 1.2)
    if person is not None:
        fill_image(person, frac, cx - w // 2, top, w, h, direction='up', color=HIGHLIGHT)
    else:
        d.rounded_rectangle([cx - w // 2, top + int(h * (1 - frac)), cx + w // 2, top + h], radius=60, fill=rgba(HIGHLIGHT, 200))
    for k in range(4):
        ph = (reveal * 3.0 + k / 4.0 + i * 0.3) % 1.0
        dy = top - 20 + int(ph * 180)
        d.ellipse([cx - 14 + (k - 2) * 50, dy, cx + 14 + (k - 2) * 50, dy + 34], fill=rgba(TEXT, int(230 * (1 - ph))))
    text(lab, cx, top + h + 30, size=36, color=TEXT, center=True)
    text(f'{v * clamp(reveal * 1.2):.0f}%', cx, top + h + 90, size=80, color=HIGHLIGHT if i == 0 else TEXT, center=True)
